import json
import math
from pathlib import Path


def load_payload(path):
    try:
        text = Path(path).read_text(encoding="utf-8")
    except UnicodeDecodeError as exc:
        raise ValueError("payload is not valid UTF-8") from exc

    def _reject_constant(token):
        raise ValueError("non-finite JSON constant: %s" % token)

    def _parse_float(token):
        value = float(token)
        if not math.isfinite(value):
            raise ValueError("non-finite JSON number: %s" % token)
        return value

    data = json.loads(text, parse_constant=_reject_constant, parse_float=_parse_float)
    if not isinstance(data, (dict, list)):
        raise ValueError("top level JSON value must be an object or array")
    return data

"""cancel_morning: select and cancel morning social events."""
import copy
import math


def _check_finite(value):
    stack = [value]
    while stack:
        item = stack.pop()
        if isinstance(item, float):
            if not math.isfinite(item):
                raise ValueError("non-finite number in payload")
        elif isinstance(item, dict):
            stack.extend(item.values())
        elif isinstance(item, list):
            stack.extend(item)
    return value


def _prepare(payloads, contract):
    if not isinstance(payloads, list):
        raise ValueError("payloads must be a list")
    if not isinstance(contract, dict):
        raise ValueError("contract must be an object")
    inputs = contract.get("inputs")
    if not isinstance(inputs, list):
        raise ValueError("contract.inputs must be a list")
    if len(payloads) != len(inputs):
        raise ValueError("payload count does not match contract.inputs")
    name = contract.get("name")
    if not isinstance(name, str) or not name.strip():
        raise ValueError("contract.name must be a non-empty string")
    _check_finite(payloads)
    _check_finite(contract)


def _unwrap(obj):
    if isinstance(obj, dict) and set(obj.keys()) == {"name", "result"}:
        return obj["result"]
    return obj


def _require_dict(obj, what):
    if not isinstance(obj, dict):
        raise ValueError("%s must be an object" % what)
    return obj


def _require_list(obj, key):
    if key not in obj:
        raise ValueError("missing field: %s" % key)
    value = obj[key]
    if not isinstance(value, list):
        raise ValueError("field %s must be a list" % key)
    return value


def _require_int(obj, key):
    if key not in obj:
        raise ValueError("missing field: %s" % key)
    value = obj[key]
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError("field %s must be an integer" % key)
    return value


def _require_bool(obj, key):
    if key not in obj:
        raise ValueError("missing field: %s" % key)
    value = obj[key]
    if not isinstance(value, bool):
        raise ValueError("field %s must be a boolean" % key)
    return value


def _require_str(obj, key):
    if key not in obj:
        raise ValueError("missing field: %s" % key)
    value = obj[key]
    if not isinstance(value, str) or not value.strip():
        raise ValueError("field %s must be a non-empty string" % key)
    return value


def _optional_str(obj, key):
    if key not in obj:
        raise ValueError("missing field: %s" % key)
    value = obj[key]
    if value is None:
        return None
    if not isinstance(value, str) or not value.strip():
        raise ValueError("field %s must be null or a non-empty string" % key)
    return value


def _validate_case(data):
    data = _require_dict(data, "calendar input")
    events = _require_list(data, "events")
    day = _require_int(data, "day")
    contacts = _require_list(data, "contacts")
    if day < 0:
        raise ValueError("day must be >= 0")
    event_ids = set()
    for event in events:
        event = _require_dict(event, "event")
        event_id = _require_str(event, "id")
        _require_int(event, "start")
        _require_int(event, "end")
        _require_bool(event, "social")
        _require_bool(event, "cancelled")
        attendees = _require_list(event, "attendees")
        for attendee in attendees:
            if not isinstance(attendee, str) or not attendee.strip():
                raise ValueError("attendee must be a non-empty string")
        if event_id in event_ids:
            raise ValueError("duplicate event id: %s" % event_id)
        event_ids.add(event_id)
    contact_ids = set()
    for contact in contacts:
        contact = _require_dict(contact, "contact")
        contact_id = _require_str(contact, "id")
        _optional_str(contact, "email")
        _optional_str(contact, "message")
        _optional_str(contact, "chat")
        if contact_id in contact_ids:
            raise ValueError("duplicate contact id: %s" % contact_id)
        contact_ids.add(contact_id)
    return events, day, contacts


def transform(payloads, contract):
    _prepare(payloads, contract)
    data = _unwrap(payloads[0])
    events, day, _contacts = _validate_case(data)
    window_start = day * 1440
    window_end = window_start + 720
    targets = [
        event
        for event in events
        if window_start <= event["start"] < window_end
        and event["social"]
        and not event["cancelled"]
        and event["end"] > event["start"]
    ]
    targets.sort(key=lambda event: event["id"])
    target_ids = {event["id"] for event in targets}
    remaining = sorted(
        (event for event in events if event["id"] not in target_ids),
        key=lambda event: event["id"],
    )
    result = {
        "cancelled": [event["id"] for event in targets],
        "snapshots": copy.deepcopy(targets),
        "remaining": copy.deepcopy(remaining),
    }
    return {"name": contract["name"], "result": result}

"""channel_directory: per-contact channel preferences."""
import math


def _check_finite(value):
    stack = [value]
    while stack:
        item = stack.pop()
        if isinstance(item, float):
            if not math.isfinite(item):
                raise ValueError("non-finite number in payload")
        elif isinstance(item, dict):
            stack.extend(item.values())
        elif isinstance(item, list):
            stack.extend(item)
    return value


def _prepare(payloads, contract):
    if not isinstance(payloads, list):
        raise ValueError("payloads must be a list")
    if not isinstance(contract, dict):
        raise ValueError("contract must be an object")
    inputs = contract.get("inputs")
    if not isinstance(inputs, list):
