"""Orchestrate every component from its file contract, then integrate and report."""
import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def _load_contracts():
    contracts = {}
    for contract_path in sorted(ROOT.rglob("contract.json")):
        if "outputs" in contract_path.relative_to(ROOT).parts:
            continue
        contract = json.loads(contract_path.read_text(encoding="utf-8"))
        if not isinstance(contract, dict):
            raise ValueError("bad contract: %s" % contract_path)
        name = contract.get("name")
        inputs = contract.get("inputs")
        output = contract.get("output")
        if not isinstance(name, str) or not name.strip():
            raise ValueError("bad contract name: %s" % contract_path)
        if not isinstance(inputs, list) or not all(isinstance(p, str) for p in inputs):
            raise ValueError("bad contract inputs: %s" % contract_path)
        if not isinstance(output, str) or not output.strip():
            raise ValueError("bad contract output: %s" % contract_path)
        if name in contracts:
            raise ValueError("duplicate component name: %s" % name)
        contracts[name] = (contract_path.parent, list(inputs), output)
    if not contracts:
        raise ValueError("no contracts found")
    return contracts


def _execution_order(contracts):
    producer = {}
    for name, (_directory, _inputs, output) in contracts.items():
        if output in producer:
            raise ValueError("conflicting outputs for %s" % output)
        producer[output] = name
    deps = {}
    for name, (_directory, inputs, _output) in contracts.items():
        deps[name] = {producer[path] for path in inputs if path in producer}
    order = []
    ready = sorted(name for name, wanted in deps.items() if not wanted)
    done = set()
    while ready:
        name = ready.pop(0)
        order.append(name)
        done.add(name)
        pending = []
        for other, wanted in deps.items():
            if other in done or other in ready or other in pending:
                continue
            if wanted <= done:
                pending.append(other)
        ready = sorted(ready + pending)
    if len(order) != len(contracts):
        raise ValueError("dependency cycle detected among components")
    return order


def main():
    try:
        contracts = _load_contracts()
        order = _execution_order(contracts)
        for name in order:
            directory = contracts[name][0]
            subprocess.run(
                [sys.executable, str(directory / "render.py")],
                cwd=str(ROOT),
                check=True,
            )
        for script in ("integrate.py", "final_report.py"):
            subprocess.run(
                [sys.executable, str(ROOT / script)],
                cwd=str(ROOT),
                check=True,
            )
    except Exception as exc:
        print("run_all failed: %s" % exc, file=sys.stderr)
        raise SystemExit(1)


if __name__ == "__main__":
    main()

"""Build the final report from the integrated core manifest."""
import hashlib
import json
import math
from pathlib import Path

ROOT = Path(__file__).resolve().parent
CORE_PATH = ROOT / "outputs" / "core_manifest.json"
REPORT_PATH = ROOT / "outputs" / "final_report.json"
TITLE = "取消日程后多渠道通知"
FALSE_FLAGS = ("complete", "checkout", "committed", "ok")
NONEMPTY_FLAGS = ("unavailable", "missing", "conflicts", "unreachable")


def _reject_constant(token):
    raise ValueError("non-finite JSON constant: %s" % token)


def _parse_float(token):
    value = float(token)
    if not math.isfinite(value):
        raise ValueError("non-finite JSON number: %s" % token)
    return value


def _is_nonempty(value):
    if value is None or value is False:
        return False
    if isinstance(value, (str, bytes, list, tuple, dict, set)):
        return len(value) > 0
    return True


def _attention(components):
    flagged = set()
    for name, result in components.items():
        if not isinstance(result, dict):
            continue
        if result.get("blocked") is True:
            flagged.add(name)
        for key in FALSE_FLAGS:
            if key in result and result[key] is False:
                flagged.add(name)
        for key in NONEMPTY_FLAGS:
            if key in result and _is_nonempty(result[key]):
                flagged.add(name)
    return sorted(flagged)


def main():
    core = json.loads(
        CORE_PATH.read_text(encoding="utf-8"),
        parse_constant=_reject_constant,
        parse_float=_parse_float,
    )
    if not isinstance(core, dict) or not isinstance(core.get("components"), dict):
        raise ValueError("core manifest must contain a components object")
    components = core["components"]
    digest = hashlib.sha256(
        json.dumps(
            core,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        ).encode("utf-8")
    ).hexdigest()
    report = {
        "title": TITLE,
        "component_count": len(components),
        "sha256": digest,
        "attention": _attention(components),
    }
    REPORT_PATH.parent.mkdir(parents=True, exist_ok=True)
    REPORT_PATH.write_text(
        json.dumps(report, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False)
        + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()

